window.PLAN_CHECKS=["week-1-output-0", "week-1-output-1", "week-1-output-2", "week-2-output-0", "week-2-output-1", "week-2-output-2", "week-3-output-0", "week-3-output-1", "week-3-output-2", "week-4-output-0", "week-4-output-1", "week-4-output-2", "week-5-output-0", "week-5-output-1", "week-5-output-2", "week-6-output-0", "week-6-output-1", "week-6-output-2", "week-7-output-0", "week-7-output-1", "week-7-output-2", "week-8-output-0", "week-8-output-1", "week-8-output-2", "week-9-output-0", "week-9-output-1", "week-9-output-2", "week-10-output-0", "week-10-output-1", "week-10-output-2", "week-11-output-0", "week-11-output-1", "week-11-output-2", "week-12-output-0", "week-12-output-1", "week-12-output-2", "module-robotics", "module-rl", "module-actor-critic", "module-imitation", "module-generative", "module-world-models", "module-planning", "module-uncertainty", "module-systems", "lab-bellman", "lab-geometry", "lab-ppo", "lab-sac", "lab-logging", "lab-bc", "lab-diffusion", "lab-dynamics", "lab-mpc", "lab-imagination", "lab-acquisition", "lab-evaluation", "release-0", "release-1", "release-2", "release-3", "release-4", "release-5"];
window.PLAN_SEARCH=[{"title": "The Physical AI program", "kind": "Overview", "href": "index.html", "text": "A detailed three-month program: robot-learning foundations, coding labs and obstruction-triggered policy adaptation. Outreach begins in week 7."}, {"title": "Weekly roadmap", "kind": "Guide", "href": "roadmap.html", "text": "01 / Weekly roadmap Twelve weeks. Clear deliverables. Six focused days each week. Separate time for theory, implementation, research and interview preparation; no double-counted hours. Your outreach boundary: private preparation during weeks 1–6. Researcher conversations, applications and follow-ups begin in week 7: . All Foundations Method Evidence Release WEEK 01 Foundations Establish the foundations and the experiment contract Understand the r"}, {"title": "Week 01: Establish the foundations and the experiment contract", "kind": "Week", "href": "week-01.html", "text": "Understand the robot-learning loop and start the research infrastructure immediately. Diagnose knowledge gaps instead of redoing material already mastered. Why does a blockage sometimes require replanning, sometimes a policy update, and sometimes a better world model?"}, {"title": "Week 02: Understand policy optimization; finish the first vertical slice", "kind": "Week", "href": "week-02.html", "text": "Implement enough RL to defend the equations and establish a repeatable task pipeline before increasing model scale. How do PPO and SAC differ, and why are imagined transitions not automatically equivalent to real off-policy data?"}, {"title": "Week 03: Build the base policy and the first predictive model", "kind": "Week", "href": "week-03.html", "text": "Get the smallest scientifically useful policy/world-model pair running. Maintain the same task across learning exercises and research. What information would a world model need to faithfully simulate your newly introduced blocker?"}, {"title": "Week 04: Make imagination useful; establish the planning baseline", "kind": "Week", "href": "week-04.html", "text": "Verify the model can support decisions and build the strongest simple alternative to policy fine-tuning. Why might a perfect-looking predicted video still be a poor training environment?"}, {"title": "Week 05: Implement the dream→update→execute loop", "kind": "Week", "href": "week-05.html", "text": "Demonstrate genuine policy parameter adaptation from imagined experience, with a fixed model during each adaptation round. Where does the policy gradient or synthetic replay signal come from when the world model is frozen?"}, {"title": "Week 06: Add real verification and freeze the research question", "kind": "Week", "href": "week-06.html", "text": "Finish the six-week preparation period with an honest pilot and a defensible experimental plan. Outreach has not started yet. Why does your method need a few real trials, and which trials should it choose?"}, {"title": "Week 07: Start outreach and run the primary comparison", "kind": "Week", "href": "week-07.html", "text": "Begin researcher conversations after six full weeks while generating the first budget-matched results. How is your experiment different from choosing the best imagined trajectory?"}, {"title": "Week 08: Test generalization and the value of active selection", "kind": "Week", "href": "week-08.html", "text": "Determine whether improvement transfers beyond the correction layouts and whether active selection actually beats random selection. What exactly is held out, and why does your split test the intended generalization?"}, {"title": "Week 09: Run targeted ablations and interrogate failure", "kind": "Week", "href": "week-09.html", "text": "Understand the mechanism and close the most consequential experimental gaps. How do you know the improvement came from your correction strategy rather than extra compute or extra data?"}, {"title": "Week 10: Write the story and package a reproducible result", "kind": "Week", "href": "week-10.html", "text": "Turn experiments into a research artifact that can be inspected, rerun and discussed in an interview. What is the single strongest result, the strongest alternative explanation, and the biggest limitation?"}, {"title": "Week 11: Close evidence gaps and rehearse deeply", "kind": "Week", "href": "week-11.html", "text": "Finish only experiments needed to substantiate the main claims, while increasing interview intensity. How would you extend this work in an industry team, and what would you deliberately avoid scaling first?"}, {"title": "Week 12: Release the artifact and complete the interview transition", "kind": "Week", "href": "week-12.html", "text": "Deliver a complete public research artifact and communicate the work with precision. What did you learn that would change how a deployed robot should use its world model?"}, {"title": "Theory and foundations", "kind": "Guide", "href": "theory.html", "text": "02 / Theory &amp; foundations Understand it well enough to use it. Build on existing modeling and research strengths. Focus new study on robotics, RL, control, learned dynamics and rigorous experiments. Before you start / 90 minutes A practical self-assessment Score each area 0–3: 0 unfamiliar; 1 can recognize; 2 can explain/derive; 3 can implement/debug and discuss limitations. Start with the lowest-scoring core areas. Skip a module only after d"}, {"title": "Robotics foundations", "kind": "Theory", "href": "theory-robotics.html", "text": "What connects a policy output to motion of a real end effector? Reference frames; SE(3), rotation matrices, quaternions, transform composition and camera-to-robot calibration. Forward and inverse kinematics; Jacobians, singularities, joint limits and task-space versus joint-space commands. Joint position, velocity and torque control; Cartesian impedance; where a learned policy sits above the controller. Observations, controller frequency, action duration, latency and synchronization. Review dynamics conceptually rather than spending weeks deriving every manipulator equation."}, {"title": "RL essentials and credit assignment", "kind": "Theory", "href": "theory-rl.html", "text": "What is actually optimized when a robot learns from experience? MDPs versus POMDPs; return, discount, occupancy and the difference between state and observation. Bellman expectation and optimality; Monte Carlo versus TD; bootstrapping, bias and variance. Policy gradients, baselines, advantage estimation and actor–critic methods. Exploration, replay, reward design, reward hacking, sparse success signals and termination versus time-limit truncation."}, {"title": "PPO, SAC and stable optimization", "kind": "Theory", "href": "theory-actor-critic.html", "text": "Which policy update is appropriate for continuous robot actions? PPO: rollout collection, old log-probabilities, clipped objective, value loss, entropy and advantage normalization. SAC: twin critics, target networks, replay, entropy temperature and reparameterized tanh-Gaussian actions. Why clipping is not a hard trust-region guarantee; why off-policy learning is attractive when robot samples are expensive. Exploding values, observation normalization, reward scale, update-to-data ratio and gradient/debugging diagnostics."}, {"title": "Imitation, offline RL and robot data", "kind": "Theory", "href": "theory-imitation.html", "text": "How do demonstrations become a robust starting policy? Behavior cloning; covariate shift; DAgger and corrective demonstrations. Offline RL, out-of-distribution action values, conservatism, and why arbitrary online updates can destroy a good offline policy. Episode boundaries, action normalization, camera alignment, observation history and dataset splitting by scene or episode. Chunked actions, execution horizons, observation horizons and the control trade-off between smoothness and reactivity."}, {"title": "Generative robot policies and VLAs", "kind": "Theory", "href": "theory-generative.html", "text": "What do diffusion, flow matching and a VLA change about the action distribution? Denoising over action chunks; timestep conditioning; noise schedules and iterative action generation. Conditional flow matching; transport from noise to actions; training objective versus inference ODE steps. VLA perception-language-action interfaces, proprioception, action representations and embodiment dependence. Fine-tuning heads/adapters versus the whole model; compute, data and inference-latency constraints."}, {"title": "Learned world models and imagination", "kind": "Theory", "href": "theory-world-models.html", "text": "What must a model predict for imagined training to improve physical behavior? Action-conditioned transition models; state, image and latent predictions; recurrent belief states under partial observation. RSSM-style posterior versus prior, reconstruction and predictive losses, reward and continuation heads. Dreamer-style actor learning in imagined rollouts versus DINO-WM-style planning with learned visual features. Compounding error, exposure bias, rollout horizon, model exploitation and the difference between a realistic video and useful dynamics."}, {"title": "Planning, control and policy adaptation", "kind": "Theory", "href": "theory-planning.html", "text": "When is searching for a new action sequence enough, and when is learning worthwhile? Receding-horizon control; CEM, random shooting and MPPI at a conceptual level. Configuration-space obstacles, RRT intuition, contact modes, non-prehensile manipulation and geometric feasibility. Task/skill sequencing versus continuous action optimization; symbolic versus neural world models. Transient replanning versus persistent policy updates; retention, transfer, compute amortization and total recovery latency."}, {"title": "Uncertainty, active correction and evaluation", "kind": "Theory", "href": "theory-uncertainty.html", "text": "Which few physical trials most improve the next recovery? Epistemic versus aleatoric uncertainty; ensembles; disagreement versus calibrated uncertainty. Active learning under policy-induced distribution shift; uncertainty sampling versus expected decision improvement. Model optimism, failure discrimination, Brier score, success reliability and predicted-versus-observed outcomes. Paired comparisons, bootstrap intervals, layout-level independence, seed variation, cost accounting and negative results."}, {"title": "Research engineering and deployment", "kind": "Theory", "href": "theory-systems.html", "text": "Can someone else rerun, debug and trust your experiment? PyTorch shapes, autograd boundaries, checkpointing, evaluation mode, vectorized environments and reproducible random generators. Dataset manifests, immutable split IDs, versioned configs, model hashes and replay-buffer provenance. Training throughput, GPU memory, inference latency, parallel rollout generation and stale observations. Robot interfaces, observation/action contracts, episode logging, reset time, command limits and recovery rollback."}, {"title": "Implementation labs", "kind": "Guide", "href": "implementation.html", "text": "03 / Implementation labs Turn concepts into working code. Twelve bounded assignments. Implement the essential mechanics yourself; reproduce and modify larger systems instead of rebuilding every framework. Spinning Up belongs here. Use it for conceptual explanations and update equations. Treat its original code as a reference with older dependencies. Use an isolated environment and current documented examples from CleanRL, Gymnasium or Stable-Base"}, {"title": "Lab 01: A blocked gridworld and Bellman backups", "kind": "Lab", "href": "lab-01.html", "text": "Make the obstruction precise before adding neural networks. Keep the start and goal fixed; change only a wall or passage. Implement deterministic transitions and value iteration with an explicit terminal state. Evaluate the original policy after adding the wall. Then recompute the policy using the updated dynamics. Plot or print the original path, blocked attempt and revised path; inspect Bellman residuals. Explain why this experiment demonstrates replanning rather than learning a missing skill."}, {"title": "Lab 02: Frames, kinematics and an IK controller", "kind": "Lab", "href": "lab-02.html", "text": "Build enough geometric intuition to debug a robot policy's actions instead of treating the controller as a black box. Implement planar two-link forward kinematics and the analytical Jacobian. Check the Jacobian against finite differences and run damped least-squares IK. Compose two homogeneous transforms and verify inverse/composition identities. Repeat the end-effector reaching example in the chosen simulator and document action units and frames."}, {"title": "Lab 03: Policy gradients, GAE and a PPO update", "kind": "Lab", "href": "lab-03.html", "text": "Own the update equations; reuse the surrounding training infrastructure. Implement discounted returns and GAE on hand-written trajectories. Implement clipped policy loss, value loss, entropy and approximate KL with explicit old log-probabilities. Read CleanRL's PPO file end to end; run one small Gymnasium task and log seeds/configs. Make one controlled intervention: remove advantage normalization or change the clipping coefficient and explain the effect."}, {"title": "Lab 04: SAC, replay and continuous actions", "kind": "Lab", "href": "lab-04.html", "text": "Use a reference SAC implementation as the continuous-control workhorse for later residual policy adaptation. Trace the actor, two critics, target critics, replay sampling and entropy-temperature update. Run a small continuous-control benchmark using the repository's documented environment. Inspect the tanh-Gaussian log-probability and action rescaling. Write one numerical comparison. Save/reload the actor and normalization state and evaluate on fixed initial states."}, {"title": "Lab 05: Robot interface and episode recorder", "kind": "Lab", "href": "lab-05.html", "text": "Create the shared interface every baseline will use. Finish a simulator episode before extensive collection. Define observe(), act(), reset() and step() with frame, units, timestamps and frequency documented. Record observations, executed actions, raw policy outputs, rewards, termination, collision/contact events and scene IDs. Save an episode manifest including calibration/configuration/checkpoint hashes and source = real, simulator or imagined. Replay the log offline; identify dropped frames, timestamp inversions and action saturation."}, {"title": "Lab 06: Behavior cloning and distribution shift", "kind": "Lab", "href": "lab-06.html", "text": "Establish what the policy can already do before you claim it improves in imagination. Collect or generate 50–100 simple demonstration trajectories in simulation; choose hardware counts only after timing resets. Train a small MLP BC policy on state observations, or a frozen visual encoder plus policy head. Split by layout/episode and evaluate closed-loop completion, not frame-level action error alone. Introduce held-out blocker placements and classify failures into perception, planning, contact/control and missing-skill cases."}, {"title": "Lab 07: A multimodal action generator", "kind": "Lab", "href": "lab-07.html", "text": "Connect your generative-modeling background to robot action distributions without spending the month training a foundation model. Create a synthetic dataset with two valid routes around an obstacle. Train a conditional denoiser or a tiny flow-matching vector field over action chunks. Compare samples against an MSE regressor whose mean may cross the obstacle. Inspect one real Diffusion Policy state example and one openpi observation/action adapter."}, {"title": "Lab 08: An action-conditioned dynamics ensemble", "kind": "Lab", "href": "lab-08.html", "text": "Start with a transparent learned dynamics model; expose its failure at the new obstruction. Fit three small models to delta-state transitions, with bootstrapped episode-level datasets. Train and evaluate on nominal and blocked transitions; preserve the training/development/test split. Compare one-step error with 5/10/20-step rollout errors and failure/success discrimination. Add a frozen visual encoder and latent dynamics if the sensor pathway and compute permit. Record this as a separate observation setting."}, {"title": "Lab 09: CEM-MPC as the essential baseline", "kind": "Lab", "href": "lab-09.html", "text": "Test whether the current learned model can solve the obstruction through search before adding policy updates. Sample bounded action sequences and score them with the learned dynamics and the same task objective used by adaptation. Refit elite action mean/variance, execute only the first action or chunk, and reobserve. Warm-start from the remaining previous plan; log model calls and wall-clock latency. Compare with random shooting and exact-physics planning as a diagnostic. Label the included 2-D point example as a teaching demo, not a robot benchmark."}, {"title": "Lab 10: Actual policy fine-tuning inside the model", "kind": "Lab", "href": "lab-10.html", "text": "Demonstrate parameter updates that persist after returning to execution; do not relabel action-sequence search as fine-tuning. Snapshot the base actor and start each adaptation comparison from the same checkpoint. Infer the current model state from recent observations. Generate short imagined rollouts from real/development anchor states. Freeze dynamics within an adaptation round. Fine-tune a residual actor using synthetic transitions and a documented SAC-style update; retain a mix of original replay for retention. Evaluate in the actual simulator or robot, then compare predicted improvement with executed improvement. Enforce an update/time budget and keep rollback available."}, {"title": "Lab 11: Choose the next few physical trials", "kind": "Lab", "href": "lab-11.html", "text": "Turn the earlier honesty project into a concrete, budget-matched correction experiment. Generate a fixed candidate pool from the current policy and legal development layouts. Define a transparent score: predicted success multiplied by outcome disagreement; use a diversity filter so top selections are not duplicates. Compare with uniform random selection from the same pool. Count selection compute and aborted real attempts. Add real transitions, update the world model between rounds, then repeat policy adaptation. Keep score weights fixed before final evaluation."}, {"title": "Lab 12: An honest evaluation report", "kind": "Lab", "href": "lab-12.html", "text": "Produce conclusions that survive a skeptical research interview. Aggregate by held-out layout and training seed; retain raw outcomes. Plot real success versus correction trials, recovery latency and total model calls. Report model optimism, success/failure discrimination and nominal-task retention together. Use layout-level paired bootstrap intervals for method differences. Declare small hardware evaluations preliminary rather than inferring significance from a few episodes."}, {"title": "Research project and experiment protocol", "kind": "Research", "href": "research.html", "text": "Detailed experiment design: task, architecture, imagined policy updates, active physical verification, baselines, budgets, data splits, metrics and decision gates."}, {"title": "Reading room and related-work boundaries", "kind": "Reading", "href": "reading.html", "text": "Paper-reading questions, evidence boundaries, world-model classifications and a novelty matrix for obstruction-triggered adaptation."}, {"title": "Interview and career preparation", "kind": "Interview", "href": "interviews.html", "text": "Thirty interview questions, coding practice, project presentation rubrics and an outreach schedule beginning in week 7."}, {"title": "Resource library and implementation references", "kind": "Guide", "href": "resources.html", "text": "07 / Resource library A small stack, used deliberately. Read the theory references deeply and pin the code you actually run. Repository availability is not a guarantee of checkpoint, GPU or robot-interface compatibility. Explain and derive Spinning Up · core RL concepts ↗ https://spinningup.openai.com/en/latest/spinningup/rl_intro.html Spinning Up · policy gradients ↗ https://spinningup.openai.com/en/latest/spinningup/rl_intro3.html Spinning Up ·"}];
